def coin_toss():
    return sum(random.choices([2,3], weights=[1,2]) for _ in range(3)) - 3

def get_line(t):
    if t == 3: return 9, '☰', '老阳（动）'
    if t == -3: return 6, '☷', '老阴（动）'
    if t == 2: return 7, '☰', '少阳'
    if t == -2: return 8, '☷', '少阴'

def divination(question, scene=''):
    random.seed()
    lines = [get_line(coin_toss()) for _ in range(6)]
    nums = [v for v,_,_ in lines]
    gua_num = sum((1 if v>0 else 0) << i for i,v in enumerate(nums)) + 1
    changed = sum(1 for _,_,t in lines if '动' in t)
    gua = next(g for g in HEX_DATA if g['n'] == gua_num)
    now = datetime.datetime.now().strftime('%Y-%m-%d %H:%M')
    advices = {
        '事业':'保持稳健，切忌急躁。顺势而为，随机应变。',
        '家庭':'以和为贵，包容理解。多沟通、少争执。',
        '感情':'真诚相待，顺其自然。缘分自有安排。',
        '学业':'循序渐进，夯实基础。量变引发质变。',
        '心理':'静心凝神，正视内心。烦恼即菩提。'
    }
    print()
    print('━'*46)
    print(f'  ☯  易道占卜  |  {now}')
    print('━'*46)
    if question: print(f'  问题：{question}')
    if scene: print(f'  场景：{scene}')
    print()
    print('  卦象（第1爻在下，第6爻在上）：')
    for i,(val,sym,t) in enumerate(reversed(lines)):
        print(f'    第{6-i}爻  {sym}  {t}')
    print()
    print(f'  ┌─{gua["name"]}卦 {gua["m"]}─┐')
    print(f'  │ {gua["d"]} │')
    print('  └'*1)
    print()
    print(f'  【开运建议】')
    print(f'  {advices.get(scene, "保持正念，正道而行。")}')
    print()
    print('━'*46)
    print('  本工具仅供参考，易经智慧在于启示而非定论。')
    print('━'*46)

if __name__ == '__main__':
    print()
